-- 0162: near-synonym sets for عَزِيز، شَدِيد، عَلِيم (Ghāfir 40:2–3) — new, none in AL fitted (near_A).
-- near_A: near-synonym (furūq, 80-KIN) sets for three Ghāfir 40:2–3 words — عَزِيز (عزز), شَدِيد (شدد), عَلِيم (علم).
-- Before: these roots had only ai_assisted AL sets (verbs, junk members, no glosses) and no lexicon_checked set.
-- Existing sets looked at and NOT reused (left alone, as asked):
--   NS:TO:TO_BECOME_OVERPOWERED_… (ظَهَرَ عَزَّ غَلَبَ اِسْتَعْلَى قَهَرَ) — verbs; holds عَزَّ, not عَزِيز.
--   NS:STRONG:STRONG_FIXED (ثَابِت رَاسِخ مَتِين مُحْكَم قَيِّمَة وُثْقَى) — firmness of things, not might.
--   NS:STRENGTH:STRENGTH (طَاقَة قُوَّة مِرَّة رُكْن مَحْل) — nouns of strength; no عزز member.
--   NS:HARD:HARD, NS:HARDNESS:HARDNESS — members are single letters / Urdu words (junk).
--   NS:TO:TO_BE_AWARE (شَعَرَ ظَهَرَ عَثَرَ عَلِمَ خَبَرَ) — verbs of coming to know; holds عَلِمَ, not عَلِيم.
-- So three new AL sets, each holding its passage lemma (global ids, every member a Qurʾān lemma, root_id set):
--   FRQ:SET:mighty      عَزِيز · قَوِيّ · مَتِين · قَاهِر
--   FRQ:SET:hard_harsh  شَدِيد · غَلِيظ · فَظّ · قَسْوَة
--   FRQ:SET:knowing     عَلِيم · خَبِير · شَهِيد · بَصِير · عَرَفَ
-- Each member: basic_gloss / contrast_note in plain English; member_src = verbatim line + block id + page
-- (lexicons via ar_ling_root_lexicon_block_v; tafsīr chunk_id = qr_tafsir_book_display_block id, cited QR:TE:<id> in note_md);
-- one evidence verse, needle cut from qr_ayah.text_uthmani, word_index checked against qr_lemma_occurrence (lx_lemma_ref = the member lemma).
-- Key book lines: al-Rāzī on 51:58 (المتين لا يُغلب / العزيز يَغلب; العزة أكمل من المتانة); Ibn ʿĀshūr on 22:74 (القوي = القدرة، العزيز = الغالب);
-- Ibn ʿĀshūr on 66:6 and al-Ālūsī on 66:6 (غلاظ الأقوال شداد الأفعال); al-Ālūsī on 3:159 (الفظ ظاهر، غليظ القلب باطن);
-- Lane p.1610 (شهيد external / خبير internal / عليم absolutely); Ibn ʿĀshūr on 66:3 (الخبير أخص من العليم; Ibn Barrajān on شهيد/بصير);
-- al-Rāghib p.560 (المعرفة أخص من العلم; «الله يعلم ولا يقال يعرف»).
-- Rejected / not added: حَكِيم — al-Rāzī on 6:18 p.144 says here it is NOT knowing (خبير already is) but soundness in His acts;
-- جَبَّار (al-Rāghib جبر p.183 has no line setting it against عزيز), غَالِب, قَهَّار, عَالِم/عَلَّام — not searched to a
-- book-stated difference in this pass; not written (candidates for a later pass).
-- al-ʿAskarī's al-Furūq is not in the corpus. Junk ai_assisted sets untouched. Idempotent: INSERT OR IGNORE only.
-- ===== FRQ:SET:mighty — Words for might and power
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set (id, set_name, description_md, slug, canonical_en, canonical_ar, pos_hint, short_summary, source_status, confidence, review_status, updated_at) VALUES ('FRQ:SET:mighty', 'العِزَّةُ وَالقُوَّةُ وَأَخَوَاتُهُمَا', 'Four Qurʾānic names of might, all about strength and winning, told apart by what each one adds: power to act (قَوِيّ), firmness that never gives (مَتِين), beating and humbling others (قَاهِر), or both never beaten and beating all (عَزِيز). Built for Ghāfir 40:2 (ٱلۡعَزِيزِ). Every difference is stated in a named book (al-Rāghib, al-Rāzī on 51:58, Ibn ʿĀshūr on 22:74, Lane).', 'furuq-mighty', 'Words for might and power', 'عَزِيز · قَوِيّ · مَتِين · قَاهِر', 'adjective', 'قَوِيّ is power to do anything; مَتِين is firm and never shaken; قَاهِر beats others and brings them low; عَزِيز is both: never beaten, and beats all.', 'lexicon_checked', 'high', 'reviewed', datetime('now'));
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:FRQ:SET:mighty:contrast', 'FRQ:SET:mighty', 'kmaps_synth', 'contrast', 'contrast', 'قَوِيّ is power to do anything; مَتِين is firm and never shaken; قَاهِر beats others and brings them low; عَزِيز is both: never beaten, and beats all. — al-Rāghib pp. 563, 693, 758, 687; al-Rāzī on 51:58 p.203; Ibn ʿĀshūr on 22:74 p.343; Lane pp. 2032, 2570', 'high');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member (id, set_id, lemma_id, nuance_note, arabic_display, arabic_bare, basic_gloss, contrast_note, source_status, claim_basis, confidence, sort_order) VALUES ('FRQ:M:mighty:aziz', 'FRQ:SET:mighty', '3d42f257c274c5d8463f1b8371', 'never beaten, and beats every opponent', 'عَزِيز', 'عزيز', 'mighty — no one can beat Him or reach Him', 'never beaten, and beats every opponent', 'lexicon_checked', 'direct_source', 'high', 1);
