INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:A67A4664', 'FRQ:M:mighty:aziz', 'razi', 'TAFSIR_BLK_BF_797a663188eaf1f477a28076', 'gloss_support', 'وفي العَزِيزِ أنَّهُ يَغْلِبُ ويَقْهَرُ ويُزِلُّ الأقْدامَ، والعِزَّةُ أكْمَلُ مِنَ المَتانَةِ', 'direct_source', 'high', 'p.203 · QR:TE:TAFSIR_BLK_BF_797a663188eaf1f477a28076 on 51:58');
