INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member_src (id, member_id, source_id, chunk_id, claim_type, claim_text, claim_basis, confidence, note_md) VALUES ('NMS:243752A1', 'FRQ:M:mighty:qawiyy', 'ibn_ashur', 'TAFSIR_BLK_BF_da00a899bd45ac7671d8c6fa', 'gloss_support', 'والقَوِيُّ: مِن أسْمائِهِ تَعالى. وهو مُسْتَعْمَلٌ في القُدْرَةِ عَلى كُلِّ مُرادٍ لَهُ. والعَزِيزُ: مِن أسْمائِهِ، وهو بِمَعْنى: الغالِبِ لِكُلِّ مُعانِدٍ.', 'direct_source', 'high', 'p.343 · QR:TE:TAFSIR_BLK_BF_da00a899bd45ac7671d8c6fa on 22:74');
