-- ===== FRQ:SET:hard_harsh — Words for hard and harsh
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set (id, set_name, description_md, slug, canonical_en, canonical_ar, pos_hint, short_summary, source_status, confidence, review_status, updated_at) VALUES ('FRQ:SET:hard_harsh', 'الشِّدَّةُ وَالغِلْظَةُ وَالقَسْوَةُ', 'Four Qurʾānic words for hardness, told apart by where the hardness is: in what is done (شَدِيد), in rough dealing (غَلِيظ), in rough words and manners (فَظّ), or in a heart that nothing moves (قَسْوَة). Built for Ghāfir 40:3 (شَدِيدِ ٱلۡعِقَابِ). Differences from al-Rāghib, Ibn ʿĀshūr and al-Ālūsī on 66:6 (غِلَاظٞ شِدَادٞ), al-Ālūsī and al-Ṭabarī on 3:159 (فَظًّا غَلِيظَ ٱلۡقَلۡبِ), and Lane.', 'furuq-hard-harsh', 'Words for hard and harsh', 'شَدِيد · غَلِيظ · فَظّ · قَسْوَة', 'mixed', 'شَدِيد is force that hurts in what is done; غَلِيظ is roughness, the opposite of gentle; فَظّ is roughness that shows in words and manners; قَسْوَة is a heart hard as stone.', 'lexicon_checked', 'high', 'reviewed', datetime('now'));
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:FRQ:SET:hard_harsh:contrast', 'FRQ:SET:hard_harsh', 'kmaps_synth', 'contrast', 'contrast', 'شَدِيد is force that hurts in what is done; غَلِيظ is roughness, the opposite of gentle; فَظّ is roughness that shows in words and manners; قَسْوَة is a heart hard as stone. — al-Rāghib pp. 447, 612, 640, 671; Ibn ʿĀshūr on 66:6 p.365; al-Ālūsī on 66:6 p.157 and on 3:159 p.106; Lane pp. 1519, 2282, 2419', 'high');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member (id, set_id, lemma_id, nuance_note, arabic_display, arabic_bare, basic_gloss, contrast_note, source_status, claim_basis, confidence, sort_order) VALUES ('FRQ:M:hard_harsh:shadid', 'FRQ:SET:hard_harsh', 'd598d16f55259b05ab7239513e', 'hard in what is done: force that hurts', 'شَدِيد', 'شديد', 'hard and strong — force that hurts, as in punishing', 'hard in what is done: force that hurts', 'lexicon_checked', 'direct_source', 'high', 1);
