-- ===== FRQ:SET:knowing — Words for knowing
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set (id, set_name, description_md, slug, canonical_en, canonical_ar, pos_hint, short_summary, source_status, confidence, review_status, updated_at) VALUES ('FRQ:SET:knowing', 'العِلْمُ وَالخِبْرَةُ وَالمَعْرِفَةُ', 'Five Qurʾānic words for knowing, told apart by HOW the knowing comes: in general and fully (عَلِيم), into the hidden inside (خَبِير), by being present (شَهِيد), by seeing (بَصِير), or through signs after thought (عَرَفَ — never said of God). Built for Ghāfir 40:2 (ٱلۡعَلِيمِ). Differences from Ibn ʿĀshūr on 66:3 (quoting Ibn Barrajān and al-Ghazālī), Lane (art. شهد), and al-Rāghib.', 'furuq-knowing', 'Words for knowing', 'عَلِيم · خَبِير · شَهِيد · بَصِير · عَرَفَ', 'mixed', 'عَلِيم is knowing in general, everything, fully; خَبِير knows the hidden inside; شَهِيد knows by being present, the outside; بَصِير knows by seeing; عَرَفَ is knowing through signs after thought, never said of God.', 'lexicon_checked', 'high', 'reviewed', datetime('now'));
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_set_src (id, set_id, source_id, chunk_id, source_role, note_md, confidence) VALUES ('NSS:FRQ:SET:knowing:contrast', 'FRQ:SET:knowing', 'kmaps_synth', 'contrast', 'contrast', 'عَلِيم is knowing in general, everything, fully; خَبِير knows the hidden inside; شَهِيد knows by being present, the outside; بَصِير knows by seeing; عَرَفَ is knowing through signs after thought, never said of God. — Lane p.1610; Ibn ʿĀshūr on 66:3 p.350; al-Rāghib pp. 580, 273, 465, 127, 560', 'high');
INSERT OR IGNORE INTO ar_ling_root_lemma_furuq_member (id, set_id, lemma_id, nuance_note, arabic_display, arabic_bare, basic_gloss, contrast_note, source_status, claim_basis, confidence, sort_order) VALUES ('FRQ:M:knowing:alim', 'FRQ:SET:knowing', '9ba7ce572be40ce777e0d44853', 'knowing in general: every thing, fully', 'عَلِيم', 'عليم', 'all-knowing — knows everything, fully and truly', 'knowing in general: every thing, fully', 'lexicon_checked', 'direct_source', 'high', 1);
